// 新私人销约段独立保存原SAY和实际结果；旧Task与handoff1..3 visitor不经本文件。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "task_personal_cancellation_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/tasks/task_source_projection.hpp"
#include "resident/domains/interaction/personal_dialogues/known_personal_dialogue_proof_codec.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status result(A& a,TaskPersonalMessageResult& r){a.field("result_id",r.result_id);a.field("request_actor_id",r.request_actor_id);a.field("command_kind",r.command_kind);a.field("request_sequence",r.request_sequence);a.field("result_revision",r.result_revision);a.field("from_tick",r.from_tick);return a.field("result_tick",r.result_tick);}
template<class A>Status record(A& a,TaskPersonalCancellationRecord& r){a.field("fact_id",r.fact_id);a.field("task_id",r.task_id);a.field("offer_id",r.offer_id);a.field("policy_id",r.policy_id);a.field("carrier_actor_id",r.carrier_actor_id);a.field("sender_actor_id",r.sender_actor_id);a.field("settlement_id",r.settlement_id);a.field("asset_receipt_fact_id",r.asset_receipt_fact_id);a.field("previous_task_status",r.previous_task_status);a.object("sender_declaration",[&](auto& c){return visit_known_personal_dialogue_proof(c,r.sender_declaration);});a.field("tick",r.tick);a.field("refunded_budget",r.refunded_budget);return a.optional("actual_result",r.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status state(A& a,TaskPersonalCancellationState& s){a.field("version",s.version);if(s.version!=1)return a.reject("UnsupportedTaskPersonalCancellationVersion");return dynamic_codec::table(a,"cancellations",s.cancellations,[](auto& c,auto& v){return record(c,v);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("TaskPersonalCancellationTooDeep");if(const auto* object=v.as<BoundaryValue::Dict>()){if(object->size()>CodecVisitor::max_items)return common_failure("TaskPersonalCancellationTooLarge");std::set<StableId> seen;for(const auto& row:*object){if(!seen.insert(row.first).second)return common_failure("DuplicateTaskPersonalCancellationField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* values=v.as<BoundaryValue::Array>()){if(values->size()>CodecVisitor::max_items)return common_failure("TaskPersonalCancellationTooLarge");for(const auto& row:*values){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Status emit_task_personal_cancellations_fields(ProjectionWriter&w,const TaskPersonalCancellationState&v){dynamic_projection::Archive a(w);return state(a,const_cast<TaskPersonalCancellationState&>(v));}
BoundaryValue encode_task_personal_cancellations(const TaskPersonalCancellationState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_personal_cancellations_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<TaskPersonalCancellationState> decode_task_personal_cancellations(const BoundaryValue& v){auto valid=unique(v);if(!valid.ok)return {false,{},valid.error};TaskPersonalCancellationState s;dynamic_codec::JsonArchive a(v);valid=state(a,s);if(valid.ok)valid=a.finish();return valid.ok?Outcome<TaskPersonalCancellationState>{true,std::move(s),{}}:Outcome<TaskPersonalCancellationState>{false,{},valid.error};}
Status visit_task_personal_cancellations_checkpoint(CodecVisitor& a,TaskPersonalCancellationState& s){return state(a,s);}
Status emit_task_personal_cancellation_fact_fields(ProjectionWriter&w,const TaskPersonalCancellationState&s,const StableId&id){dynamic_projection::Archive a(w);Status valid;if(const auto*row=s.cancellations.find(id)){valid=record(a,const_cast<TaskPersonalCancellationRecord&>(*row));}else return common_failure("TaskPersonalCancellationSourceMissing",id);if(!valid.ok)return valid;return w.status();}
Outcome<BoundaryValue> encode_task_personal_cancellation_fact(const TaskPersonalCancellationState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_personal_cancellation_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
